class TreeNode:
    def __init__(self, val=0, left=None, right=None, nextRight=None):
        self.val = val
        self.left = left
        self.right = right
        self.nextRight = nextRight

def connect(root):
    if not root:
        return
    queue = [root]
    while queue:
        size = len(queue)
        for i in range(size):
            node = queue.pop(0)
            if i < size - 1:
                node.nextRight = queue[0]
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

def level_order_traversal(root):
    if not root:
        return []
    result = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        result.append(node)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return result

def inorder_traversal(root):
    if not root:
        return []
    return inorder_traversal(root.left) + [root] + inorder_traversal(root.right)

import sys
from collections import deque

input = sys.stdin.read().strip().split('\n')
nodes = list(map(int, input[0].split()))
edges = list(map(int, input[1].split()))

node_map = {i: TreeNode(i) for i in nodes}
for i in range(0, len(edges), 2):
    parent = edges[i]
    child = edges[i + 1]
    if node_map[parent].left is None:
        node_map[parent].left = node_map[child]
    else:
        node_map[parent].right = node_map[child]

connect(node_map[nodes[0]])

level_order = level_order_traversal(node_map[nodes[0]])
inorder = inorder_traversal(node_map[nodes[0]])

print(' '.join(str(node.val) for node in level_order))
print(' '.join(str(node.val) for node in inorder))
